# Typhoon Doksuri Remnant Rainfall Phase Segmentation

You are an event-timeline analyst segmenting the late July to early August 2023 rainfall process caused by Typhoon Doksuri remnants over Beijing, Hebei, Tianjin, and the Haihe river system. The task is to divide the event into physically meaningful phases with computed transition evidence.

Use only the local CSX-095 event package. Select package-relative evidence for hourly rainfall, daily rainfall, reported extreme rainfall anchors, and wind background.

Segment the event into these phases:

- sustained wet-hour rainfall phase;
- three-day concentration phase;
- report-calibrated extreme rainfall phase;
- wind-dominance rejection phase.

Compute:

- `wet_hour_fraction = wet_hours / window_hours`;
- `longest_wet_run_share = longest_wet_run_hours / wet_hours`;
- `peak_hour_share = peak_hour_mm / hourly_total_mm`;
- `wet_hour_mean_mm = hourly_total_mm / wet_hours`;
- `window_mean_mm_per_hour = hourly_total_mm / window_hours`;
- `max_3day_share = max_3day_daily_sum_mm / daily_total_mm`;
- `peak_day_share = peak_day_mm / daily_total_mm`;
- `daily_to_hourly_total_ratio = daily_total_mm / hourly_total_mm`;
- `report_avg_intensity_mm_per_hour = report_avg_mm / report_duration_hours`;
- `report_avg_to_hourly_total_ratio = report_avg_mm / hourly_total_mm`;
- `reservoir_to_report_avg_ratio = reservoir_mm / report_avg_mm`;
- `single_point_to_report_avg_ratio = single_point_max_mm / report_avg_mm`;
- `peak_wind_ms` and `wind_energy_proxy = peak_wind_ms^2`.

Return this JSON shape:

```json
{
  "target_family": "doksuri_rainfall_phase_segmentation",
  "phases": [
    {"phase": "sustained_wet_hour_rainfall", "time_window": "", "dominant_process": "", "computed_value": {}, "transition_basis": ""},
    {"phase": "three_day_concentration", "time_window": "", "dominant_process": "", "computed_value": {}, "transition_basis": ""},
    {"phase": "report_calibrated_extreme_rainfall", "time_window": "", "dominant_process": "", "computed_value": {}, "transition_basis": ""},
    {"phase": "wind_dominance_rejection", "time_window": "", "dominant_process": "", "computed_value": {}, "transition_basis": ""}
  ],
  "phase_checks": [
    {"row_id": "rainfall_persistence", "computed_value": {}, "result": ""},
    {"row_id": "three_day_concentration", "computed_value": {}, "result": ""},
    {"row_id": "report_intensity_alignment", "computed_value": {}, "result": ""},
    {"row_id": "wind_rejection", "computed_value": {}, "result": ""}
  ],
  "final_label": ""
}
```

Use `persistent_remnant_cyclone_rainfall_supported` only when the rainfall persistence, three-day concentration, report-intensity alignment, and wind rejection phases all support a rainfall-dominant remnant-cyclone timeline.

compute_gt_py:
#!/usr/bin/env python3
"""Compute ground truth for CSX-095_Q1 from the local CSX-095 record."""

from __future__ import annotations

import json
import math
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-095_Q1"
EVENT_ID = "CSX-095"
TARGET_FAMILY = "doksuri_rainfall_phase_segmentation"
FINAL_LABEL = "persistent_remnant_cyclone_rainfall_supported"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        text = data.strip()
        if text:
            self.parts.append(text)


def repo_root() -> Path:
    here = Path(__file__).resolve()
    for parent in [here.parent, *here.parents]:
        candidate = parent / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
        if candidate.is_dir():
            return parent
    raise FileNotFoundError("CSX-095 record directory was not found")


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def load_json(rel_path: str) -> Any:
    return json.loads((package_root() / rel_path).read_text(encoding="utf-8-sig"))


def html_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package_root() / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return re.sub(r"\s+", " ", " ".join(parser.parts)).strip()


def number_from_match(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not parse required value with pattern: {pattern}")
    return float(match.group(1).replace(",", ""))


def longest_true_run(flags: list[bool]) -> int:
    longest = 0
    current = 0
    for flag in flags:
        current = current + 1 if flag else 0
        longest = max(longest, current)
    return longest


def max_rolling_sum(values: list[float], window: int) -> float:
    return max(sum(values[i : i + window]) for i in range(len(values) - window + 1))


def round_float(value: float, digits: int) -> float:
    return round(float(value), digits)


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer structure",
                "points": 3,
                "description": "Returns JSON only with target_family, four phases, four phase_checks, and final_label.",
                "partial_credit": "Award 1-2 points for valid JSON with one missing row or one misplaced field.",
            },
            {
                "name": "Rainfall persistence row",
                "points": 4,
                "description": "Computes 120 h, 0.700 wet-hour fraction, 0.929 longest-run share, 0.0889 peak-hour share, 2.344 mm/wet-hour, 1.641 mm/window-hour, and the pass result.",
                "partial_credit": "Award 2-3 points for mostly correct values with one formula or rounding error.",
            },
            {
                "name": "Three-day concentration row",
                "points": 3,
                "description": "Computes 0.926 max 3-day share, 0.441 peak-day share, 1.120 daily-to-hourly ratio, and the pass result.",
                "partial_credit": "Award 1-2 points for two correct ratios or a correct result with incomplete arithmetic.",
            },
            {
                "name": "Report intensity row",
                "points": 4,
                "description": "Computes 3.988 mm/hour, 1.681 report-to-hourly ratio, 2.250 reservoir-to-average ratio, 3.097 single-point-to-average ratio, and the pass result.",
                "partial_credit": "Award 2-3 points for most values correct with one missing report ratio.",
            },
            {
                "name": "Wind rejection row",
                "points": 3,
                "description": "Computes 38.5 km/h, 10.69 m/s, 114.3 proxy, applies the below-15 m/s test, and rejects wind-dominant calibration.",
                "partial_credit": "Award 1-2 points for the right rejection with incomplete conversion or proxy work.",
            },
            {
                "name": "Final label and bounded interpretation",
                "points": 3,
                "description": "Gives the exact final label and ties the interpretation to persistent rainfall, daily/report alignment, and wind rejection without extra realized-loss or action statements.",
                "partial_credit": "Award 1-2 points for a nearly correct label or an interpretation that is correct but too broad.",
            },
        ],
    }


def compute() -> dict[str, Any]:
    event_meta = load_json("metadata/event.json")
    open_meteo = load_json("data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")
    nasa_power = load_json("data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json")
    local_report_text = html_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")
    regional_report_text = html_text("data/other/other_001_WMO_-_Typhoons_trigger_record-breaking_rainfall_in_China.html")

    hourly_precip = [float(value or 0.0) for value in open_meteo["hourly"]["precipitation"]]
    hourly_wind_kmh = [float(value or 0.0) for value in open_meteo["hourly"]["wind_speed_10m"]]
    wet_flags = [value > 0.0 for value in hourly_precip]
    power_precip = nasa_power["properties"]["parameter"]["PRECTOTCORR"]
    daily_values = [float(value) for value in power_precip.values()]

    hourly_total = sum(hourly_precip)
    daily_total = sum(daily_values)
    wet_hours = sum(wet_flags)
    window_hours = len(hourly_precip)
    longest_wet_run_hours = longest_true_run(wet_flags)
    peak_hour_mm = max(hourly_precip)
    peak_wind_kmh = max(hourly_wind_kmh)
    peak_wind_ms = round_float(peak_wind_kmh / 3.6, 2)
    peak_day_mm = max(daily_values)
    max_3day_daily_sum_mm = max_rolling_sum(daily_values, 3)

    report_avg_mm = number_from_match(r"average rainfall of ([0-9.]+) millimeters", local_report_text)
    report_duration_hours = int(number_from_match(r"over ([0-9]+) hours", local_report_text))
    single_point_max_mm = number_from_match(r"single point of\s*([0-9,]+) millimeters", local_report_text)
    reservoir_mm = number_from_match(r"It logged ([0-9.]+) millimeters of rain", regional_report_text)

    rainfall_persistence = {
        "window_hours": window_hours,
        "wet_hour_fraction": round_float(wet_hours / window_hours, 3),
        "longest_wet_run_share": round_float(longest_wet_run_hours / wet_hours, 3),
        "peak_hour_share": round_float(peak_hour_mm / hourly_total, 4),
        "wet_hour_mean_mm": round_float(hourly_total / wet_hours, 3),
        "window_mean_mm_per_hour": round_float(hourly_total / window_hours, 3),
    }
    three_day_concentration = {
        "max_3day_share": round_float(max_3day_daily_sum_mm / daily_total, 3),
        "peak_day_share": round_float(peak_day_mm / daily_total, 3),
        "daily_to_hourly_total_ratio": round_float(daily_total / hourly_total, 3),
    }
    report_intensity_alignment = {
        "report_avg_intensity_mm_per_hour": round_float(report_avg_mm / report_duration_hours, 3),
        "report_avg_to_hourly_total_ratio": round_float(report_avg_mm / hourly_total, 3),
        "reservoir_to_report_avg_ratio": round_float(reservoir_mm / report_avg_mm, 3),
        "single_point_to_report_avg_ratio": round_float(single_point_max_mm / report_avg_mm, 3),
    }
    wind_rejection = {
        "peak_wind_ms": peak_wind_ms,
        "peak_wind_kmh": peak_wind_kmh,
        "wind_energy_proxy": round_float(math.pow(peak_wind_ms, 2), 1),
    }

    phase_checks = [
        {
            "row_id": "rainfall_persistence",
            "computed_value": rainfall_persistence,
            "result": "pass_persistent_multiday_rainfall",
        },
        {
            "row_id": "three_day_concentration",
            "computed_value": three_day_concentration,
            "result": "pass_multiday_concentrated_rainfall",
        },
        {
            "row_id": "report_intensity_alignment",
            "computed_value": report_intensity_alignment,
            "result": "pass_report_extreme_rainfall_alignment",
        },
        {
            "row_id": "wind_rejection",
            "computed_value": wind_rejection,
            "result": "reject_wind_dominant_calibration",
        },
    ]
    phases = [
        {
            "phase": "sustained_wet_hour_rainfall",
            "time_window": "120-hour event window",
            "dominant_process": "persistent remnant-cyclone rainfall",
            "computed_value": rainfall_persistence,
            "transition_basis": "A long wet run and low peak-hour share show persistence rather than a single-hour burst.",
        },
        {
            "phase": "three_day_concentration",
            "time_window": "wettest three daily totals",
            "dominant_process": "multi-day rainfall concentration",
            "computed_value": three_day_concentration,
            "transition_basis": "Most daily rainfall sits in a three-day block while the peak day remains below half of the total.",
        },
        {
            "phase": "report_calibrated_extreme_rainfall",
            "time_window": "83-hour reported extreme-rainfall anchor",
            "dominant_process": "report-scale rainfall alignment",
            "computed_value": report_intensity_alignment,
            "transition_basis": "Report-average intensity and reported maxima align with extreme rainfall rather than weak background rain.",
        },
        {
            "phase": "wind_dominance_rejection",
            "time_window": "event wind background",
            "dominant_process": "rainfall-dominant remnant timeline",
            "computed_value": wind_rejection,
            "transition_basis": "Peak wind is below the wind-dominance cutoff, so wind cannot replace rainfall as the timeline control.",
        },
    ]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "phases": phases,
            "phase_checks": phase_checks,
            "final_label": FINAL_LABEL,
        },
        "key_values": {
            "event_name": event_meta["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "event_window": "2023-07-29 to 2023-08-02",
            "hourly_total_mm": round_float(hourly_total, 1),
            "wet_hours": wet_hours,
            "longest_wet_run_hours": longest_wet_run_hours,
            "peak_hour_mm": peak_hour_mm,
            "daily_total_mm": round_float(daily_total, 2),
            "max_3day_daily_sum_mm": round_float(max_3day_daily_sum_mm, 2),
            "peak_day_mm": round_float(peak_day_mm, 2),
            "report_avg_mm": report_avg_mm,
            "report_duration_hours": report_duration_hours,
            "reservoir_mm": reservoir_mm,
            "single_point_max_mm": single_point_max_mm,
            "peak_wind_kmh": peak_wind_kmh,
        },
        "derived_metrics": {
            "phases": phases,
            "phase_checks": phase_checks,
            "final_label": FINAL_LABEL,
        },
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
                "data/other/other_001_WMO_-_Typhoons_trigger_record-breaking_rainfall_in_China.html",
                "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json",
                "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
            ],
        },
    }

def main() -> None:
    output = Path(__file__).resolve().parent / "computed_gt.json"
    computed_gt = compute()
    output.write_text(json.dumps(computed_gt, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
